/**
 * Lightweight markdown renderer for chat messages.
 * Handles: tables, bold, italic, links, inline code, code blocks, headers, lists.
 */

import type { JSX } from "react";

interface MessageContentProps {
  content: string;
  className?: string;
}

/** Parse a markdown table string into header + rows */
function parseTable(block: string): { headers: string[]; rows: string[][] } | null {
  const lines = block
    .trim()
    .split("\n")
    .filter((l) => l.trim());
  if (lines.length < 2) return null;

  const parseCells = (line: string) =>
    line
      .replace(/^\|/, "")
      .replace(/\|$/, "")
      .split("|")
      .map((c) => c.trim());

  const headers = parseCells(lines[0]);
  // Check line[1] is separator (---|----|---)
  const sep = lines[1];
  if (!/^[\s|:-]+$/.test(sep)) return null;

  const rows = lines.slice(2).map(parseCells);
  return { headers, rows };
}

/** Render inline markdown: bold, italic, code, links */
function renderInline(text: string): (string | JSX.Element)[] {
  const parts: (string | JSX.Element)[] = [];
  // Pattern: **bold**, *italic*, `code`, [text](url), @mention
  const regex = /(\*\*(.+?)\*\*)|(\*(.+?)\*)|(`(.+?)`)|(\[([^\]]+)\]\(([^)]+)\))|(@[\w가-힣]+)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      parts.push(text.slice(lastIndex, match.index));
    }
    if (match[1]) {
      // **bold**
      parts.push(
        <strong key={key++} className="font-bold text-white">
          {match[2]}
        </strong>,
      );
    } else if (match[3]) {
      // *italic*
      parts.push(
        <em key={key++} className="italic">
          {match[4]}
        </em>,
      );
    } else if (match[5]) {
      // `code`
      parts.push(
        <code key={key++} className="px-1 py-0.5 bg-gray-700 text-emerald-300 rounded text-xs font-mono">
          {match[6]}
        </code>,
      );
    } else if (match[7]) {
      // [text](url)
      parts.push(
        <a
          key={key++}
          href={match[9]}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-400 underline hover:text-blue-300"
        >
          {match[8]}
        </a>,
      );
    } else if (match[10]) {
      // @mention
      parts.push(
        <span key={key++} className="px-1 py-0.5 bg-blue-500/20 text-blue-300 rounded font-medium">
          {match[10]}
        </span>,
      );
    }
    lastIndex = match.index + match[0].length;
  }
  if (lastIndex < text.length) {
    parts.push(text.slice(lastIndex));
  }
  return parts.length > 0 ? parts : [text];
}

export default function MessageContent({ content, className = "" }: MessageContentProps) {
  // Split content into blocks (code blocks, tables, and regular text)
  const blocks: { type: "text" | "code" | "table"; content: string }[] = [];

  // Extract fenced code blocks first
  const codeBlockRegex = /```(\w*)\n?([\s\S]*?)```/g;
  let lastIdx = 0;
  let cbMatch: RegExpExecArray | null;

  while ((cbMatch = codeBlockRegex.exec(content)) !== null) {
    if (cbMatch.index > lastIdx) {
      blocks.push({ type: "text", content: content.slice(lastIdx, cbMatch.index) });
    }
    blocks.push({ type: "code", content: cbMatch[2].trimEnd() });
    lastIdx = cbMatch.index + cbMatch[0].length;
  }
  if (lastIdx < content.length) {
    blocks.push({ type: "text", content: content.slice(lastIdx) });
  }

  // Further split text blocks to extract tables
  const finalBlocks: typeof blocks = [];
  for (const block of blocks) {
    if (block.type !== "text") {
      finalBlocks.push(block);
      continue;
    }

    // Look for table patterns (lines starting with |)
    const lines = block.content.split("\n");
    let tableLines: string[] = [];
    let textLines: string[] = [];

    for (const line of lines) {
      if (/^\s*\|/.test(line)) {
        if (textLines.length > 0) {
          finalBlocks.push({ type: "text", content: textLines.join("\n") });
          textLines = [];
        }
        tableLines.push(line);
      } else {
        if (tableLines.length > 0) {
          finalBlocks.push({ type: "table", content: tableLines.join("\n") });
          tableLines = [];
        }
        textLines.push(line);
      }
    }
    if (tableLines.length > 0) {
      finalBlocks.push({ type: "table", content: tableLines.join("\n") });
    }
    if (textLines.length > 0) {
      finalBlocks.push({ type: "text", content: textLines.join("\n") });
    }
  }

  return (
    <div className={`space-y-2 ${className}`}>
      {finalBlocks.map((block, bi) => {
        if (block.type === "code") {
          return (
            <pre
              key={bi}
              className="bg-gray-800 border border-gray-600 rounded-lg px-3 py-2 text-xs font-mono text-green-300 overflow-x-auto whitespace-pre-wrap"
            >
              {block.content}
            </pre>
          );
        }

        if (block.type === "table") {
          const table = parseTable(block.content);
          if (table) {
            return (
              <div key={bi} className="overflow-x-auto rounded-lg border border-gray-600">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-gray-700/80">
                      {table.headers.map((h, hi) => (
                        <th
                          key={hi}
                          className="px-2.5 py-1.5 text-left font-semibold text-gray-200 border-b border-gray-600 whitespace-nowrap"
                        >
                          {renderInline(h)}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {table.rows.map((row, ri) => (
                      <tr key={ri} className={ri % 2 === 0 ? "bg-gray-800/50" : "bg-gray-800/30"}>
                        {row.map((cell, ci) => (
                          <td
                            key={ci}
                            className="px-2.5 py-1.5 text-gray-300 border-b border-gray-700/50 whitespace-nowrap"
                          >
                            {renderInline(cell)}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          }
          // Fallback: render as text if not a valid table
          return <span key={bi}>{block.content}</span>;
        }

        // Text block: handle headers, lists, paragraphs
        const textLines = block.content.split("\n");
        return (
          <div key={bi}>
            {textLines.map((line, li) => {
              const trimmed = line.trim();
              if (!trimmed) return <div key={li} className="h-1" />;

              // Headers
              if (trimmed.startsWith("### ")) {
                return (
                  <div key={li} className="font-bold text-white text-sm mt-1">
                    {renderInline(trimmed.slice(4))}
                  </div>
                );
              }
              if (trimmed.startsWith("## ")) {
                return (
                  <div key={li} className="font-bold text-white text-sm mt-1">
                    {renderInline(trimmed.slice(3))}
                  </div>
                );
              }
              if (trimmed.startsWith("# ")) {
                return (
                  <div key={li} className="font-bold text-white mt-1">
                    {renderInline(trimmed.slice(2))}
                  </div>
                );
              }

              // Unordered list
              if (/^[-*]\s/.test(trimmed)) {
                return (
                  <div key={li} className="flex gap-1.5 items-start">
                    <span className="text-gray-500 mt-0.5 shrink-0">•</span>
                    <span>{renderInline(trimmed.slice(2))}</span>
                  </div>
                );
              }

              // Ordered list
              const olMatch = trimmed.match(/^(\d+)[.)]\s(.*)/);
              if (olMatch) {
                return (
                  <div key={li} className="flex gap-1.5 items-start">
                    <span className="text-gray-500 mt-0.5 shrink-0 min-w-[1em] text-right">{olMatch[1]}.</span>
                    <span>{renderInline(olMatch[2])}</span>
                  </div>
                );
              }

              // Horizontal rule
              if (/^[-*_]{3,}$/.test(trimmed)) {
                return <hr key={li} className="border-gray-600 my-1" />;
              }

              // Normal paragraph
              return <div key={li}>{renderInline(trimmed)}</div>;
            })}
          </div>
        );
      })}
    </div>
  );
}


type FriendlyOfficeReportSection = { key: string; title: string; paragraphs: string[]; hiddenParagraphs?: number };
/** Read explicit report labels only. This parser never generates a conclusion or rewrites facts. */
function parseFriendlyOfficeReport(content: string): { sections: FriendlyOfficeReportSection[]; olderFormat: boolean; technicalHidden: boolean } {
  const labels: Record<string, { key: string; title: string }> = {
    "한 줄 결론": { key: "conclusion", title: "한 줄 결론" },
    "한줄 결론": { key: "conclusion", title: "한 줄 결론" },
    "결론": { key: "conclusion", title: "결론" },
    "핵심 결론": { key: "conclusion", title: "핵심 결론" },
    "쉽게 말하면": { key: "conclusion", title: "쉽게 말하면" },
    "지금 할 일": { key: "actions", title: "지금 할 일" },
    "다음 할 일": { key: "actions", title: "다음 할 일" },
    "다음 행동": { key: "actions", title: "다음 행동" },
    "추천 행동": { key: "actions", title: "추천 행동" },
    "우선 할 일": { key: "actions", title: "우선 할 일" },
    "내가 결정할 것": { key: "decisions", title: "내가 결정할 것" },
    "사용자가 결정할 것": { key: "decisions", title: "사용자가 결정할 것" },
    "사용자 결정": { key: "decisions", title: "사용자 결정" },
    "결정이 필요한 것": { key: "decisions", title: "결정이 필요한 것" },
    "선택이 필요한 것": { key: "decisions", title: "선택이 필요한 것" },
    "다음 선택지": { key: "options", title: "다음 선택지" },
    "아직 확인하지 못한 것": { key: "unknown", title: "아직 확인하지 못한 것" },
    "확인하지 못한 것": { key: "unknown", title: "확인하지 못한 것" },
    "미확인": { key: "unknown", title: "보고서에 적힌 미확인 내용" },
    "확인 필요": { key: "unknown", title: "확인이 필요한 내용" },
    "완료되어 제외한 일": { key: "completed", title: "보고서에 적힌 완료 항목" },
    "근거": { key: "technical", title: "근거" },
    "읽은 문서·버전": { key: "technical", title: "읽은 문서·버전" },
    "읽은 문서": { key: "technical", title: "읽은 문서" },
    "기술 근거": { key: "technical", title: "기술 근거" },
    "상세 근거": { key: "technical", title: "상세 근거" },
  };
  const labelNames = Object.keys(labels).sort((a, b) => b.length - a.length);
  const escaped = labelNames.map(label => label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|");
  // Some old outputs put bold section labels in one paragraph. Split only those known labels.
  const normalized = content.replace(new RegExp("(?=\\*\\*(?:" + escaped + ")[：:]?\\*\\*)", "g"), "\n\n");
  const found = new Map<string, FriendlyOfficeReportSection>();
  let current: { key: string; title: string } | null = null;
  let buffer: string[] = [];
  let technicalHidden = false;
  const opaque = (text: string) => /\b[a-f0-9]{16,}\b|(?:\/workspace\/|\/run\/|(?:^|\s)(?:src|docs|server|mobile)\/[\w./-]+)|\b(?:Revision|sha256|sourceHead|permissionDigest)\b/i.test(text);
  function flush() {
    const text = buffer.join("\n").trim(); buffer = [];
    if (!text || !current) return;
    if (current.key === "technical") { technicalHidden = true; return; }
    // Keep a mixed technical paragraph intact in the original rather than cutting away qualifiers.
    const paragraphs = text.split(/\n\s*\n/).map(value => value.trim()).filter(Boolean);
    for (const paragraph of paragraphs) {
      if (opaque(paragraph)) { technicalHidden = true; const section: FriendlyOfficeReportSection = found.get(current.key) || { key: current.key, title: current.title, paragraphs: [] }; section.hiddenParagraphs = (section.hiddenParagraphs || 0) + 1; found.set(current.key, section); continue; }
      const section = found.get(current.key) || { key: current.key, title: current.title, paragraphs: [] };
      section.paragraphs.push(paragraph); found.set(current.key, section);
    }
  }
  for (const line of normalized.split(/\r?\n/)) {
    const plain = line.replace(/^\s*#{1,6}\s*/, "").replace(/^\s*\d+[.)]\s+/, "").replace(/\*\*/g, "").trim();
    const label = labelNames.find(name => plain === name || plain.startsWith(name + ":") || plain.startsWith(name + "："));
    if (label) {
      flush(); current = labels[label];
      const rest = plain.slice(label.length).replace(/^[：:]\s*/, "").trim();
      if (rest) buffer.push(rest);
    } else if (current) buffer.push(line);
  }
  flush();
  const order = ["conclusion", "actions", "decisions", "options", "unknown", "completed"];
  return { sections: order.flatMap(key => found.has(key) ? [found.get(key)!] : []), olderFormat: !found.has("conclusion") || !found.has("actions"), technicalHidden };
}

export function FriendlyOfficeReport({ content, taskTitle }: { content: string; taskTitle?: string }) {
  const report = parseFriendlyOfficeReport(content);
  return <section aria-label="읽기 쉬운 보고서" className="min-w-0 space-y-4 text-sm leading-7">
    {taskTitle && <p className="break-words text-base font-semibold">{taskTitle}</p>}
    {report.olderFormat && <p className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm leading-6" role="note">이전 보고서라 핵심이 따로 정리되어 있지 않아요. 원문은 아래에서 볼 수 있어요.</p>}
    {report.sections.map(section => <section key={section.key} aria-label={section.title} className="min-w-0 rounded-xl border border-slate-500/30 p-3">
      <h4 className="mb-2 text-base font-semibold">{section.title}</h4>
      <div className="space-y-3 break-words">{!!section.hiddenParagraphs && <p className="text-sm leading-6 opacity-80">이 항목은 설명과 조건이 함께 있어요. 빠뜨리지 않도록 아래 원문에서 확인해주세요.</p>}{section.paragraphs.map((paragraph, index) => <div key={index} className="min-w-0 [overflow-wrap:anywhere]"><MessageContent content={paragraph}/></div>)}</div>
    </section>)}
    {!report.sections.length && <p className="text-sm leading-6">아직 결론과 할 일이 따로 정리되어 있지 않아요. 아래에서 보고서 전체를 볼 수 있어요.</p>}
    {report.technicalHidden && <p className="text-xs leading-5 opacity-75">문서 경로와 버전은 아래 근거에 모았어요.</p>}
    <details className="min-w-0 rounded-xl border border-slate-500/30 p-3">
      <summary className="cursor-pointer text-sm font-semibold">근거와 원문 전체 보기</summary>
      <p className="my-2 text-xs leading-5 opacity-75">저장된 원문 그대로입니다. 위 항목에 표시되지 않은 내용도 모두 포함합니다.</p>
      <div className="min-w-0 whitespace-normal break-words [overflow-wrap:anywhere]"><MessageContent content={content}/></div>
    </details>
  </section>;
}

import type { RefObject } from "react";
import type { Agent, Message } from "../../types";
import type { DecisionOption } from "../chat/decision-request";
import AgentAvatar from "../AgentAvatar";
import MessageContent, {FriendlyOfficeReport} from "../MessageContent";

type Tr = (ko: string, en: string, ja?: string, zh?: string) => string;

interface StreamingMessageLike {
  message_id: string;
  agent_id: string;
  agent_name: string;
  agent_avatar: string;
  content: string;
}

interface ChatMessageListProps {
  selectedAgent: Agent | null;
  visibleMessages: Message[];
  agents: Agent[];
  spriteMap: ReturnType<typeof import("../AgentAvatar").buildSpriteMap>;
  locale: string;
  tr: Tr;
  getAgentName: (agent: Agent | null | undefined) => string;
  decisionRequestByMessage: Map<string, { options: DecisionOption[] }>;
  decisionReplyKey: string | null;
  onDecisionOptionReply: (message: Message, option: DecisionOption) => void;
  onDecisionManualDraft: (option: DecisionOption) => void;
  streamingMessage?: StreamingMessageLike | null;
  messagesEndRef: RefObject<HTMLDivElement | null>;
}

function formatTime(ts: number, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(ts));
}

function TypingIndicator() {
  return (
    <div className="flex items-center gap-1 px-4 py-2">
      <div className="flex items-center gap-1 rounded-2xl rounded-bl-sm bg-gray-700 px-4 py-2">
        <span className="h-2 w-2 animate-bounce rounded-full bg-gray-400" style={{ animationDelay: "0ms" }} />
        <span className="h-2 w-2 animate-bounce rounded-full bg-gray-400" style={{ animationDelay: "150ms" }} />
        <span className="h-2 w-2 animate-bounce rounded-full bg-gray-400" style={{ animationDelay: "300ms" }} />
      </div>
    </div>
  );
}

function normalizeMessageSenderName(msg: Message): string {
  return typeof msg.sender_name === "string" ? msg.sender_name.trim() : "";
}

function normalizeMessageSenderAvatar(msg: Message): string {
  const avatar = typeof msg.sender_avatar === "string" ? msg.sender_avatar.trim() : "";
  return avatar || "🤖";
}

function buildFallbackSenderAgent(msg: Message): Agent | undefined {
  const displayName = normalizeMessageSenderName(msg) || msg.sender_id || "";
  if (!displayName) return undefined;
  return {
    id: msg.sender_id || `msg-sender-${msg.id}`,
    name: displayName,
    name_ko: displayName,
    name_ja: displayName,
    name_zh: displayName,
    department_id: null,
    role: "junior",
    cli_provider: "api",
    avatar_emoji: normalizeMessageSenderAvatar(msg),
    personality: null,
    status: "idle",
    current_task_id: null,
    stats_tasks_done: 0,
    stats_xp: 0,
    created_at: msg.created_at,
  };
}

export default function ChatMessageList({
  selectedAgent,
  visibleMessages,
  agents,
  spriteMap,
  locale,
  tr,
  getAgentName,
  decisionRequestByMessage,
  decisionReplyKey,
  onDecisionOptionReply,
  onDecisionManualDraft,
  streamingMessage,
  messagesEndRef,
}: ChatMessageListProps) {
  const isStreamingForAgent = Boolean(
    streamingMessage && selectedAgent && streamingMessage.agent_id === selectedAgent.id,
  );

  return (
    <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-4 py-4">
      {visibleMessages.length === 0 ? (
        <div className="flex h-full flex-col items-center justify-center gap-4 text-center">
          <div className="text-6xl">💬</div>
          <div>
            <p className="font-medium text-gray-400">
              {tr("대화를 시작해보세요! 👋", "Start a conversation! 👋", "会話を始めましょう! 👋", "开始对话吧! 👋")}
            </p>
            <p className="mt-1 text-sm text-gray-600">
              {selectedAgent
                ? tr(
                    `${getAgentName(selectedAgent)}에게 메시지를 보내보세요`,
                    `Send a message to ${getAgentName(selectedAgent)}`,
                    `${getAgentName(selectedAgent)}にメッセージを送ってみましょう`,
                    `给 ${getAgentName(selectedAgent)} 发送一条消息吧`,
                  )
                : tr(
                    "전체 에이전트에게 공지를 보내보세요",
                    "Send an announcement to all agents",
                    "すべてのエージェントに告知を送ってみましょう",
                    "给所有代理发送一条公告吧",
                  )}
            </p>
          </div>
        </div>
      ) : (
        <>
          {visibleMessages.map((msg) => {
            const isCeo = msg.sender_type === "ceo";
            const isDirective = msg.message_type === "directive";
            const isSystem = msg.sender_type === "system" || msg.message_type === "announcement" || isDirective;

            const senderAgent =
              msg.sender_agent ?? agents.find((agent) => agent.id === msg.sender_id) ?? buildFallbackSenderAgent(msg);
            const senderNameFromPayload = normalizeMessageSenderName(msg);
            const senderName = isCeo
              ? tr("CEO", "CEO")
              : isSystem
                ? tr("시스템", "System", "システム", "系统")
                : getAgentName(senderAgent) || senderNameFromPayload || tr("알 수 없음", "Unknown", "不明", "未知");
            const decisionRequest = decisionRequestByMessage.get(msg.id);

            if (msg.sender_type === "agent" && msg.receiver_type === "all") {
              return (
                <div key={msg.id} className="flex items-end gap-2">
                  <AgentAvatar agent={senderAgent} spriteMap={spriteMap} size={28} />
                  <div className="flex max-w-[75%] flex-col gap-1">
                    <span className="px-1 text-xs text-gray-500">{senderName}</span>
                    <div className="announcement-reply-bubble rounded-2xl rounded-bl-sm border border-yellow-500/20 bg-gray-700/70 px-4 py-2.5 text-sm text-gray-100 shadow-md">
                      {msg.message_type === "report" ? <FriendlyOfficeReport content={msg.content}/> : <MessageContent content={msg.content} />}
                    </div>
                    {decisionRequest && (
                      <div className="rounded-xl border border-indigo-500/30 bg-indigo-500/10 px-2 py-2">
                        <p className="text-[11px] font-medium text-indigo-200">
                          {tr("의사결정 요청", "Decision request", "意思決定リクエスト", "决策请求")}
                        </p>
                        <div className="mt-1.5 space-y-1">
                          {decisionRequest.options.map((option) => {
                            const key = `${msg.id}:${option.number}`;
                            const isBusy = decisionReplyKey === key;
                            return (
                              <button
                                key={key}
                                type="button"
                                onClick={() => onDecisionOptionReply(msg, option)}
                                disabled={isBusy}
                                className="decision-inline-option w-full rounded-md px-2 py-1.5 text-left text-[11px] transition disabled:opacity-60"
                              >
                                {isBusy
                                  ? tr("전송 중...", "Sending...", "送信中...", "发送中...")
                                  : `${option.number}. ${option.label}`}
                              </button>
                            );
                          })}
                        </div>
                        <button
                          type="button"
                          onClick={() => onDecisionManualDraft(decisionRequest.options[0])}
                          className="mt-2 text-[11px] text-indigo-200/90 underline underline-offset-2 hover:text-indigo-100"
                        >
                          {tr("직접 답변 작성", "Write custom reply", "カスタム返信を作成", "编写自定义回复")}
                        </button>
                      </div>
                    )}
                    <span className="px-1 text-xs text-gray-600">{formatTime(msg.created_at, locale)}</span>
                  </div>
                </div>
              );
            }

            if (isSystem || msg.receiver_type === "all") {
              return (
                <div key={msg.id} className="flex flex-col items-center gap-1">
                  {isDirective && (
                    <span className="rounded-full border border-red-500/30 bg-red-500/10 px-2 py-0.5 text-xs font-bold text-red-400">
                      {tr("업무지시", "Directive", "業務指示", "业务指示")}
                    </span>
                  )}
                  <div
                    className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-center text-sm shadow-sm ${
                      isDirective
                        ? "border border-red-500/30 bg-red-500/15 text-red-300"
                        : "announcement-message-bubble border border-yellow-500/30 bg-yellow-500/15 text-yellow-300"
                    }`}
                  >
                    {msg.message_type === "report" ? <FriendlyOfficeReport content={msg.content}/> : <MessageContent content={msg.content} />}
                  </div>
                  <span className="text-xs text-gray-600">{formatTime(msg.created_at, locale)}</span>
                </div>
              );
            }

            if (isCeo) {
              return (
                <div key={msg.id} className="flex flex-col items-end gap-1">
                  <span className="px-1 text-xs text-gray-500">{tr("CEO", "CEO")}</span>
                  <div className="max-w-[80%] rounded-2xl rounded-br-sm bg-blue-600 px-4 py-2.5 text-sm text-white shadow-md">
                    {msg.message_type === "report" ? <FriendlyOfficeReport content={msg.content}/> : <MessageContent content={msg.content} />}
                  </div>
                  <span className="px-1 text-xs text-gray-600">{formatTime(msg.created_at, locale)}</span>
                </div>
              );
            }

            return (
              <div key={msg.id} className="flex items-end gap-2">
                <AgentAvatar agent={senderAgent} spriteMap={spriteMap} size={28} />
                <div className="flex max-w-[75%] flex-col gap-1">
                  <span className="px-1 text-xs text-gray-500">{senderName}</span>
                  <div className="rounded-2xl rounded-bl-sm bg-gray-700 px-4 py-2.5 text-sm text-gray-100 shadow-md">
                    {msg.message_type === "report" ? <FriendlyOfficeReport content={msg.content}/> : <MessageContent content={msg.content} />}
                  </div>
                  {decisionRequest && (
                    <div className="rounded-xl border border-indigo-500/30 bg-indigo-500/10 px-2 py-2">
                      <p className="text-[11px] font-medium text-indigo-200">
                        {tr("의사결정 요청", "Decision request", "意思決定リクエスト", "决策请求")}
                      </p>
                      <div className="mt-1.5 space-y-1">
                        {decisionRequest.options.map((option) => {
                          const key = `${msg.id}:${option.number}`;
                          const isBusy = decisionReplyKey === key;
                          return (
                            <button
                              key={key}
                              type="button"
                              onClick={() => onDecisionOptionReply(msg, option)}
                              disabled={isBusy}
                              className="decision-inline-option w-full rounded-md px-2 py-1.5 text-left text-[11px] transition disabled:opacity-60"
                            >
                              {isBusy
                                ? tr("전송 중...", "Sending...", "送信中...", "发送中...")
                                : `${option.number}. ${option.label}`}
                            </button>
                          );
                        })}
                      </div>
                      <button
                        type="button"
                        onClick={() => onDecisionManualDraft(decisionRequest.options[0])}
                        className="mt-2 text-[11px] text-indigo-200/90 underline underline-offset-2 hover:text-indigo-100"
                      >
                        {tr("직접 답변 작성", "Write custom reply", "カスタム返信を作成", "编写自定义回复")}
                      </button>
                    </div>
                  )}
                  <span className="px-1 text-xs text-gray-600">{formatTime(msg.created_at, locale)}</span>
                </div>
              </div>
            );
          })}

          {isStreamingForAgent && streamingMessage?.content && (
            <div className="flex items-end gap-2">
              <AgentAvatar agent={selectedAgent ?? undefined} spriteMap={spriteMap} size={28} />
              <div className="flex max-w-[75%] flex-col gap-1">
                <span className="px-1 text-xs text-gray-500">{getAgentName(selectedAgent)}</span>
                <div className="rounded-2xl rounded-bl-sm border border-emerald-500/20 bg-gray-700 px-4 py-2.5 text-sm text-gray-100 shadow-md">
                  <MessageContent content={streamingMessage.content} />
                  <span className="ml-0.5 inline-block h-4 w-1.5 animate-pulse rounded-sm bg-emerald-400 align-text-bottom" />
                </div>
              </div>
            </div>
          )}

          {selectedAgent && selectedAgent.status === "working" && !isStreamingForAgent && (
            <div className="flex items-end gap-2">
              <AgentAvatar agent={selectedAgent} spriteMap={spriteMap} size={28} />
              <TypingIndicator />
            </div>
          )}
        </>
      )}

      <div ref={messagesEndRef} />
    </div>
  );
}
